import React, { useEffect, useState } from "react";
import {
  Alert,
  Badge,
  Button,
  Card,
  Checkbox,
  Divider,
  Drawer,
  Form,
  Input,
  message,
  notification,
  Skeleton,
  Space,
} from "antd";
import { MdOutlineHome, MdOutlineHomeWork, MdOutlineLocationOn } from "react-icons/md";
import "../../style/header.css";
import axios from "axios"
import { MdMyLocation } from "react-icons/md";
import ShowMap from "../cart/ShowMap";
import { Col, Row } from "react-bootstrap"
import { AddAddress } from "../apiService/api";
import { useAuth } from "../auth/context/authContext";
import NotImage from "../../assest/png/notdeliverd.png"

const AddressDrawer = ({ ShowSaveAddress }) => {
  const [open, setOpen] = useState(false);
  const [lat, setLat] = useState("")
  const [lng, setLng] = useState("")
  const [form] = Form.useForm();
  const [pinLocation, setPinLocation] = useState([])
  const [formLoader, setFormLoader] = useState(false)
  // const [typeSelect,setTypeSelect]=useState(false)
  const [addTypes, setAddsType] = useState("")
  const { token } = useAuth()
  const [alerts, setAlerts] = useState(false)
  const [noService, setNoService] = useState(null)
  const [isLoading, setIsLoading] = useState(false)


  const { address } = pinLocation
  // const { suburb, state_district, state, postcode } = address
  console.log("address", address)

  const showDrawer = () => {
    setOpen(true);
  };

  const cartClose = () => {
    setOpen(false);
  };


  useEffect(() => {
    async function getPinLocation() {
      const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;

      const response = await axios.get(
        `https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${apiKey}`
      );
      setFormLoader(true)
      if (response.data.status === "OK") {
        const userLocation = response.data.results[0];
        setPinLocation(userLocation);  // Set the state with the user’s location data
        setFormLoader(false)
      }

    }
    if (lat != "" && lng != "") {
      getPinLocation()
    }


  }, [lat, lng]);


  useEffect(() => {
    if (pinLocation.length != 0) {
      form.setFieldsValue({
        area: pinLocation?.formatted_address
      })
    }
  }, [pinLocation])

  const onFinish = async (value) => {
    const body = {

      latitude: lat,
      longitude: lng,
      area: value.area,
      flatNumber: value.flatNumber,
      floorNumber: value.floorNumber,
      apartmentName: value.apartmentName,
      howToReach: value.howToReach,
      mobileNo: value.mobileNo,
      profileName: value.profileName,
      addressName: value.addressName,
      addressType: addTypes
    }

    if (addTypes == "") {
      notification.warning({
        placement: "topLeft",
        message: "Please Select Address Type !",
      });
    } else {

      setIsLoading(true)
      try {
        await AddAddress(token, body)
          .then((res) => {
            console.log("add address", res);
            if (res.status == 201) {
              notification.success({
                placement: "topRight",
                message: "Address added Successfully !",
              });
              setPinLocation([])
              setAddsType("")
              setOpen(false);
              onReset()
              setIsLoading(false)
              ShowSaveAddress()
              setAlerts(false)
            } else if (res.status === 202) {
              setOpen(true)
              setNoService(res.data.message)
              setIsLoading(false)
            } else if (res.status === 200) {
              // setOpen(true)
              message.warning(res.data.message)
              setIsLoading(false)
            }

          })
          .catch((err) => {
            console.log(err);
          });
      } catch (error) {
        console.log(error);
        setIsLoading(false)
      }
    }
  };

  const onReset = () => {
    form.resetFields();
  };
  const onFinishFailed = (value) => {
    console.log(value)
  }
  const addressType = [
    {
      id: 1,
      title: "HOME",
      icon: <MdOutlineHome />
    },
    {
      id: 2,
      title: "OFFICE",
      icon: <MdOutlineHomeWork />

    },
    {
      id: 2,
      title: "OTHERS",
      icon: <MdOutlineLocationOn />

    },
  ]

  const handleAddress = (add) => {
    setAddsType(add)
    console.log(add)
  }

  const validateMaxLength = (_, value) => {
    if (value && value.length > 10) {
      return Promise.reject(new Error('Please Enter Valid Number !'));
    }
    return Promise.resolve();
  };

  return (
    <>
      <div className="Add_Addre">
        <Button onClick={showDrawer} shape="round" block>
          <MdMyLocation className="loc_iocns" /> Add New  Address
        </Button>
      </div>
      <Drawer
        title="Fill Complete address"
        onClose={cartClose}
        open={open}
        // placement="left"
        width={600}
      >
        {alerts ? <Alert message="Note : Please Drag Map Your exact Location" type="info" showIcon closable /> : null}
        <Card>
          <ShowMap setLat={setLat} setLng={setLng} lat={lat} lng={lng} setAlerts={setAlerts} />
          <div className="add_form">
            {formLoader == true ? <Skeleton /> :
              <Form
                form={form}
                layout="vertical"
                name="basic"
                style={{
                  maxWidth: 600,
                }}
                onFinish={onFinish}
                onFinishFailed={onFinishFailed}
              >
                <Form.Item
                  label="Area/Locality"
                  name="area"
                  rules={[
                    {
                      required: true,
                      message: "Please Search you area on on Map",
                    },
                  ]}
                >
                  <Input placeholder="Enter Area" disabled />
                </Form.Item>
                <Row>
                  <Col md={6}>

                    <Form.Item
                      label="House/Flat Number"
                      name="flatNumber"
                      rules={[
                        {
                          required: true,
                          message: "Please Enter your flatNumber!",
                        },
                      ]}
                    >
                      <Input placeholder="Enter Flat Number" />
                    </Form.Item>
                  </Col>
                  <Col md={6}>
                    <Form.Item
                      label="Floor Number"
                      name="floorNumber"

                    >
                      <Input placeholder="Enter Floor Number " />
                    </Form.Item>

                  </Col>
                </Row>


                <Row>
                  <Col md={6}>

                    <Form.Item
                      label="Apartment/Building Name"
                      name="apartmentName"
                    // rules={[
                    //   {
                    //     required: true,
                    //     message: "Please Enter your apartment Name",
                    //   },
                    // ]}
                    >
                      <Input placeholder="Enter Apartment" />
                    </Form.Item>
                  </Col>
                  <Col md={6}>

                    <Form.Item
                      label="Mobile Number"
                      name="mobileNo"
                      rules={[

                        {
                          pattern: /^[0-9]*$/,
                          message: 'Please Enter only Numbers!',
                        },
                        { validator: validateMaxLength }
                      ]}
                    >
                      <Input placeholder="Enter Mobile Number" />
                    </Form.Item>
                  </Col>
                </Row>

                <Row>
                  <Col md={6}>
                    <Form.Item
                      label="Profile Name"
                      name="profileName"
                    >
                      <Input placeholder="Enter Profile Name (e.g. My Home)" />
                    </Form.Item>
                  </Col>
                  <Col md={6}>
                    <Form.Item
                      label="Address Name"
                      name="addressName"
                    >
                      <Input placeholder="Enter Address Name (e.g. Dad's place)" />
                    </Form.Item>
                  </Col>
                </Row>

                <Row>
                  <Col md={12}>

                    <Form.Item
                      label="How to reach"
                      name="howToReach"
                      rules={[
                        {
                          required: true,
                          message: "Please Enter How To Reach",
                        },
                      ]}
                    >
                      <Input placeholder="Enter Landmark " />
                    </Form.Item>
                  </Col>


                  <Col md={12}>

                    <Form.Item
                      label="Save address as a"
                      name="addressType"


                    >
                      <div className="show_loc_type" >
                        {addressType.map((add) => (
                          <div className={` ${addTypes == add.title && "homeSelected"}`}>
                            <Card key={add.id} hoverable onClick={() => handleAddress(add.title)}>
                              <Space>
                                <span >{add.icon}</span>
                                <p>{add.title}</p>
                              </Space>
                            </Card>
                          </div>
                        ))}
                      </div>
                    </Form.Item>
                  </Col>
                </Row>

                <Form.Item>
                  <div className="add_address_btn">
                    <Button loading={isLoading} type="primary" htmlType="submit" shape="round">
                      Submit
                    </Button>
                  </div>
                </Form.Item>
              </Form>}
          </div>
          {
            noService ? <div className="no_service">
              <img src={NotImage} />
              <p>{noService}</p>
            </div> : null}
        </Card >
      </Drawer >
    </>
  );
};

export default AddressDrawer;
